create table public.corrective_action_reviews(id uuid primary key default gen_random_uuid(),review_type text not null check(review_type in('material_incident','repeated_incident','control_failure')),recurrence_key text not null check(char_length(btrim(recurrence_key))between 3 and 120),title text not null check(char_length(btrim(title))between 3 and 180),problem_statement text not null check(char_length(btrim(problem_statement))between 10 and 4000),root_cause text not null check(char_length(btrim(root_cause))between 10 and 4000),contributing_factors jsonb not null default'[]'check(jsonb_typeof(contributing_factors)='array'),impact_summary text not null check(char_length(btrim(impact_summary))between 10 and 4000),status text not null default'action_in_progress'check(status in('draft','action_in_progress','verification','closed')),owner_user_id uuid not null references auth.users(id)on delete restrict,due_at timestamptz not null,effectiveness_measure text,verification_evidence text,verified_by uuid references auth.users(id)on delete set null,verified_at timestamptz,created_by uuid not null references auth.users(id)on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),closed_at timestamptz);
create table public.corrective_action_review_exceptions(review_id uuid not null references public.corrective_action_reviews(id)on delete cascade,exception_id uuid not null references public.operational_exceptions(id)on delete restrict,created_at timestamptz not null default now(),primary key(review_id,exception_id));
create table public.preventive_actions(id uuid primary key default gen_random_uuid(),review_id uuid not null references public.corrective_action_reviews(id)on delete cascade,action text not null check(char_length(btrim(action))between 10 and 2000),owner_user_id uuid not null references auth.users(id)on delete restrict,due_at timestamptz not null,status text not null default'open'check(status in('open','in_progress','implemented','verified','cancelled')),implementation_evidence text,verification_evidence text,verified_by uuid references auth.users(id)on delete set null,verified_at timestamptz,task_id uuid references public.tasks_reminders(id)on delete set null,created_by uuid not null references auth.users(id)on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index corrective_action_reviews_open_key_uidx on public.corrective_action_reviews(lower(recurrence_key))where status<>'closed';create index corrective_action_reviews_queue_idx on public.corrective_action_reviews(status,due_at);create index preventive_actions_queue_idx on public.preventive_actions(status,due_at);
alter table public.corrective_action_reviews enable row level security;alter table public.corrective_action_review_exceptions enable row level security;alter table public.preventive_actions enable row level security;revoke all on public.corrective_action_reviews,public.corrective_action_review_exceptions,public.preventive_actions from public,anon,authenticated;grant all on public.corrective_action_reviews,public.corrective_action_review_exceptions,public.preventive_actions to service_role;

create function public.detect_repeated_operational_exceptions(p_days integer default 90,p_minimum_count integer default 2)returns table(pattern_key text,category text,entity_type text,exception_count bigint,critical_or_high_count bigint,latest_at timestamptz,exception_ids uuid[])language sql stable security definer set search_path=public,pg_temp as $$select e.category||':'||e.entity_type,e.category,e.entity_type,count(*),count(*)filter(where e.severity in('critical','high')),max(e.created_at),array_agg(e.id order by e.created_at desc)from public.operational_exceptions e where public.is_admin()and e.created_at>=now()-make_interval(days=>least(greatest(coalesce(p_days,90),1),730))group by e.category,e.entity_type having count(*)>=least(greatest(coalesce(p_minimum_count,2),2),20)order by count(*)desc,max(e.created_at)desc$$;

create function public.create_corrective_action_review(p_review_type text,p_recurrence_key text,p_title text,p_problem_statement text,p_root_cause text,p_contributing_factors jsonb,p_impact_summary text,p_owner_user_id uuid,p_due_at timestamptz,p_exception_ids uuid[],p_actions jsonb)returns uuid language plpgsql security definer set search_path=public,pg_temp as $$declare v_actor uuid:=auth.uid();v_id uuid;v_item jsonb;v_action uuid;v_task uuid;v_owner uuid;v_due timestamptz;v_count integer;begin if v_actor is null or not public.is_admin()then raise exception'Owner/admin access required';end if;if p_review_type not in('material_incident','repeated_incident','control_failure')then raise exception'Invalid review type';end if;if char_length(btrim(coalesce(p_recurrence_key,'')))not between 3 and 120 or char_length(btrim(coalesce(p_title,'')))not between 3 and 180 or char_length(btrim(coalesce(p_problem_statement,'')))not between 10 and 4000 or char_length(btrim(coalesce(p_root_cause,'')))not between 10 and 4000 or char_length(btrim(coalesce(p_impact_summary,'')))not between 10 and 4000 then raise exception'Review details are incomplete';end if;if jsonb_typeof(coalesce(p_contributing_factors,'[]'))<>'array'or jsonb_typeof(coalesce(p_actions,'[]'))<>'array'then raise exception'Factors and actions must be arrays';end if;select count(distinct x)into v_count from unnest(coalesce(p_exception_ids,'{}'))x;if v_count<1 or(select count(*)from public.operational_exceptions where id=any(p_exception_ids))<>v_count then raise exception'Choose valid source exceptions';end if;if p_review_type='repeated_incident'and v_count<2 then raise exception'Repeated incident review requires at least two exceptions';end if;if jsonb_array_length(p_actions)<1 or jsonb_array_length(p_actions)>20 then raise exception'Add 1 to 20 preventive actions';end if;if not exists(select 1 from public.staff_profiles where user_id=p_owner_user_id and active)then raise exception'Review owner must be active staff';end if;if p_due_at<=now()then raise exception'Review deadline must be in the future';end if;
insert into public.corrective_action_reviews(review_type,recurrence_key,title,problem_statement,root_cause,contributing_factors,impact_summary,owner_user_id,due_at,created_by)values(p_review_type,lower(btrim(p_recurrence_key)),btrim(p_title),btrim(p_problem_statement),btrim(p_root_cause),coalesce(p_contributing_factors,'[]'),btrim(p_impact_summary),p_owner_user_id,p_due_at,v_actor)returning id into v_id;insert into public.corrective_action_review_exceptions(review_id,exception_id)select v_id,x from unnest(p_exception_ids)x group by x;
for v_item in select value from jsonb_array_elements(p_actions)loop v_owner:=coalesce(nullif(v_item->>'owner_user_id','')::uuid,p_owner_user_id);v_due:=coalesce(nullif(v_item->>'due_at','')::timestamptz,p_due_at);if char_length(btrim(coalesce(v_item->>'action','')))<10 then raise exception'Every preventive action needs at least 10 characters';end if;if not exists(select 1 from public.staff_profiles where user_id=v_owner and active)then raise exception'Action owner must be active staff';end if;if v_due<=now()then raise exception'Action deadline must be in the future';end if;insert into public.preventive_actions(review_id,action,owner_user_id,due_at,created_by)values(v_id,btrim(v_item->>'action'),v_owner,v_due,v_actor)returning id into v_action;insert into public.tasks_reminders(title,task_type,entity_type,entity_id,due_at,priority,assigned_to,notes,created_by,automation_key)values('Prevent recurrence: '||left(btrim(v_item->>'action'),150),'internal','preventive_action',v_action,v_due,'high',v_owner,'Implement the corrective action and attach evidence before independent verification.',v_actor,'preventive-action:'||v_action)returning id into v_task;update public.preventive_actions set task_id=v_task where id=v_action;end loop;
insert into public.audit_events(actor_user_id,event_type,entity_type,entity_id,metadata)values(v_actor,'corrective_action_review.created','corrective_action_review',v_id,jsonb_build_object('review_type',p_review_type,'recurrence_key',lower(btrim(p_recurrence_key)),'exception_count',v_count,'action_count',jsonb_array_length(p_actions)));return v_id;end$$;

create function public.list_corrective_action_reviews(p_status text default null,p_limit integer default 200)returns jsonb language sql stable security definer set search_path=public,pg_temp as $$select case when public.is_admin()then coalesce(jsonb_agg(to_jsonb(x)order by x.created_at desc),'[]')else'[]'::jsonb end from(select r.*,(select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'action',a.action,'owner_user_id',a.owner_user_id,'due_at',a.due_at,'status',a.status,'implementation_evidence',a.implementation_evidence,'verification_evidence',a.verification_evidence,'verified_at',a.verified_at,'task_id',a.task_id)order by a.due_at),'[]')from public.preventive_actions a where a.review_id=r.id)actions,(select array_agg(x.exception_id)from public.corrective_action_review_exceptions x where x.review_id=r.id)exception_ids from public.corrective_action_reviews r where(p_status is null or r.status=p_status)order by(r.status<>'closed'and r.due_at<now())desc,r.created_at desc limit least(greatest(coalesce(p_limit,200),1),500))x$$;

create function public.update_preventive_action(p_action_id uuid,p_status text,p_implementation_evidence text default null,p_verification_evidence text default null)returns void language plpgsql security definer set search_path=public,pg_temp as $$declare v_actor uuid:=auth.uid();v_old public.preventive_actions%rowtype;v_status text:=lower(btrim(coalesce(p_status,'')));begin if v_actor is null or not public.is_admin()then raise exception'Owner/admin access required';end if;if v_status not in('open','in_progress','implemented','verified','cancelled')then raise exception'Invalid action status';end if;select*into v_old from public.preventive_actions where id=p_action_id for update;if not found then raise exception'Preventive action not found';end if;if v_status in('implemented','verified')and char_length(btrim(coalesce(p_implementation_evidence,v_old.implementation_evidence,'')))<10 then raise exception'Implementation evidence is required';end if;if v_status='verified'and char_length(btrim(coalesce(p_verification_evidence,'')))<10 then raise exception'Independent verification evidence is required';end if;update public.preventive_actions set status=v_status,implementation_evidence=coalesce(nullif(btrim(coalesce(p_implementation_evidence,'')),''),implementation_evidence),verification_evidence=case when v_status='verified'then btrim(p_verification_evidence)else verification_evidence end,verified_by=case when v_status='verified'then v_actor else verified_by end,verified_at=case when v_status='verified'then now()else verified_at end,updated_at=now()where id=p_action_id;update public.tasks_reminders set status=case when v_status in('verified','cancelled')then'done'else status end,completed_at=case when v_status in('verified','cancelled')then coalesce(completed_at,now())else completed_at end where id=v_old.task_id;insert into public.audit_events(actor_user_id,event_type,entity_type,entity_id,metadata)values(v_actor,'preventive_action.updated','preventive_action',p_action_id,jsonb_build_object('from_status',v_old.status,'to_status',v_status,'review_id',v_old.review_id));end$$;

create function public.close_corrective_action_review(p_review_id uuid,p_effectiveness_measure text,p_verification_evidence text)returns void language plpgsql security definer set search_path=public,pg_temp as $$declare v_actor uuid:=auth.uid();v_review public.corrective_action_reviews%rowtype;begin if v_actor is null or not public.is_admin()then raise exception'Owner/admin access required';end if;if char_length(btrim(coalesce(p_effectiveness_measure,'')))<10 or char_length(btrim(coalesce(p_verification_evidence,'')))<10 then raise exception'Effectiveness measure and verification evidence are required';end if;select*into v_review from public.corrective_action_reviews where id=p_review_id for update;if not found then raise exception'Review not found';end if;if exists(select 1 from public.preventive_actions where review_id=p_review_id and status<>'verified')then raise exception'Every preventive action must be verified before closure';end if;update public.corrective_action_reviews set status='closed',effectiveness_measure=btrim(p_effectiveness_measure),verification_evidence=btrim(p_verification_evidence),verified_by=v_actor,verified_at=now(),closed_at=now(),updated_at=now()where id=p_review_id;insert into public.audit_events(actor_user_id,event_type,entity_type,entity_id,metadata)values(v_actor,'corrective_action_review.closed','corrective_action_review',p_review_id,jsonb_build_object('recurrence_key',v_review.recurrence_key,'verified_action_count',(select count(*)from public.preventive_actions where review_id=p_review_id)));end$$;
revoke execute on function public.detect_repeated_operational_exceptions(integer,integer),public.create_corrective_action_review(text,text,text,text,text,jsonb,text,uuid,timestamptz,uuid[],jsonb),public.list_corrective_action_reviews(text,integer),public.update_preventive_action(uuid,text,text,text),public.close_corrective_action_review(uuid,text,text)from public,anon;grant execute on function public.detect_repeated_operational_exceptions(integer,integer),public.create_corrective_action_review(text,text,text,text,text,jsonb,text,uuid,timestamptz,uuid[],jsonb),public.list_corrective_action_reviews(text,integer),public.update_preventive_action(uuid,text,text,text),public.close_corrective_action_review(uuid,text,text)to authenticated,service_role;
